170	// (native Entire) placements are skipped: `repo mirror list` is the mirror
171	// directory, and a native repo has no GitHub mirror clone URL to advertise
172	// (fabricating an entire://.../gh/... URL for one would point nowhere). A repo
173	// with only native placements therefore doesn't appear here. A mirror whose
174	// cluster host can't be resolved (unknown slug, or a publicUrl that failed
175	// validation) still lists, but with an empty clone URL that renders as "-" —
176	// the row is kept, no unsafe URL is printed.
177	func buildRepoDir(entries []coreapi.RepoIndexEntry, hostBySlug map[string]string) []repoDirRow {
178		var rows []repoDirRow
179		for _, e := range entries {
180			name := e.FullName
181			if name == "" {
182				name = e.Name
183			}
184			private := strings.EqualFold(e.Visibility, "private")
185			if cand, ok := e.Candidate.Get(); ok {
186				status := "owner-only"
187				if cand.Onboardable {
188					status = "available"
189				}
190				rows = append(rows, repoDirRow{Repo: name, Private: private, Status: status, Access: string(cand.Access)})
191				continue
192			}
193			owner, repo, _ := strings.Cut(name, "/")
194			for _, p := range e.Placements {
195				if !p.Mirror {
196					continue // native Entire repo, not a GitHub mirror
197				}
198				clone := ""
199				if host := hostBySlug[p.ClusterSlug]; host != "" && repo != "" {
200					clone = mirrorCloneURL(host, owner, repo)
201				}
202				rows = append(rows, repoDirRow{Repo: name, CloneURL: clone, Private: private, Status: string(p.Status), Cluster: p.ClusterSlug})
203			}
204		}
205		return rows
206	}
