208	// sortRepoDir orders directory rows in place by the --sort spec, matching the
209	// old sortMirrors: by the named column ascending (case-insensitive), tie-broken
210	// by repo name then clone URL for a deterministic order. A '-' prefix reverses.
211	func sortRepoDir(rows []repoDirRow, spec string) error {
212		col, desc, err := parseSortColumn(spec, repoDirColumns)
213		if err != nil {
214			return err
215		}
216		key := func(r repoDirRow) string {
217			switch col {
218			case colCloneURL:
219				return strings.ToLower(r.CloneURL)
220			case colPrivate:
221				return yesNo(r.Private)
222			case colStatus:
223				return strings.ToLower(r.Status)
224			case colAccess:
225				return strings.ToLower(r.Access)
226			default: // name -> tiebreak alone
227				return ""
228			}
229		}
230		slices.SortStableFunc(rows, func(a, b repoDirRow) int {
231			c := cmp.Compare(key(a), key(b))
232			if c == 0 {
233				c = cmp.Compare(strings.ToLower(a.Repo), strings.ToLower(b.Repo))
234			}
235			if c == 0 {
236				c = cmp.Compare(strings.ToLower(a.CloneURL), strings.ToLower(b.CloneURL))
237			}
238			if desc {
239				return -c
240			}
241			return c
242		})
243		return nil
244	}
