246	// filterByName keeps items whose owner/repo name contains substr (case-
247	// insensitive). The control plane already filters by owner/provider/cluster
248	// server-side but not by name, so `repo mirror list --name` narrows that last
249	// dimension client-side. nameOf returns the item's displayed identifier — the
250	// callers pass the owner/repo form shown in the NAME column, so a value copied
251	// from the table (e.g. acme/web) matches the row it came from. An empty substr
252	// returns items unchanged.
253	func filterByName[T any](items []T, nameOf func(T) string, substr string) []T {
254		substr = strings.TrimSpace(substr)
255		if substr == "" {
256			return items
257		}
258		substr = strings.ToLower(substr)
259		out := make([]T, 0, len(items))
260		for _, it := range items {
261			if strings.Contains(strings.ToLower(nameOf(it)), substr) {
262				out = append(out, it)
263			}
264		}
265		return out
266	}
