566	// repoDirLocalFilters carries the client-side filter/sort flags
567	// of `repo mirror list`. privateSet distinguishes an unset --private (keep
568	// all) from an explicit --private/--private=false (tri-state flag).
569	type repoDirLocalFilters struct {
570		name, owner, cluster, status, access string
571		privateSet, private                  bool
572		sortSpec                             string
