575	// applyRepoDirLocal runs the client-side filter/sort pipeline
576	// over rows. The server cannot filter or sort the directory, so this applies
577	// only to the rows the caller fetched. hostBySlug is needed because --cluster
578	// accepts a public host while rows carry only the placement slug.
579	func applyRepoDirLocal(f repoDirLocalFilters, rows []repoDirRow, hostBySlug map[string]string) ([]repoDirRow, error) {
580		rows = filterByName(rows, func(r repoDirRow) string { return r.Repo }, f.name)
581		if f.owner != "" {
582			rows = slices.DeleteFunc(rows, func(r repoDirRow) bool {
583				o, _, _ := strings.Cut(r.Repo, "/")
584				return !strings.EqualFold(o, f.owner)
585			})
586		}
587		if f.cluster != "" {
588			// Candidates are cluster-agnostic, so --cluster keeps only onboarded
589			// rows on the named cluster. Placements carry only a slug, but the
590			// clone URLs this command prints identify clusters by public host
591			// (e.g. aws-us-east-2.entire.io). Accept either form so a host
592			// copied from a clone URL still matches.
593			rows = slices.DeleteFunc(rows, func(r repoDirRow) bool {
594				return !strings.EqualFold(r.Cluster, f.cluster) &&
595					!strings.EqualFold(hostBySlug[r.Cluster], f.cluster)
596			})
597		}
598		if f.status != "" {
599			// Exact (case-insensitive) match on the displayed STATUS cell, which
600			// spans both row types: mirrors (ready/processing/failed/suspended)
601			// and candidates (available/owner-only).
602			rows = slices.DeleteFunc(rows, func(r repoDirRow) bool {
603				return !strings.EqualFold(r.Status, f.status)
604			})
605		}
606		if f.access != "" {
607			// ACCESS is candidate-only (read/write/admin); mirror rows carry
608			// none, so --access naturally narrows to matching candidates.
609			rows = slices.DeleteFunc(rows, func(r repoDirRow) bool {
610				return !strings.EqualFold(r.Access, f.access)
611			})
612		}
613		if f.privateSet {
614			rows = slices.DeleteFunc(rows, func(r repoDirRow) bool {
615				return r.Private != f.private
616			})
617		}
618		if err := sortRepoDir(rows, f.sortSpec); err != nil {
619			return nil, err
620		}
621		return rows, nil
622	}
