665		var noPager, all bool
666		cmd := &cobra.Command{
667			Use:   "list",
668			Short: "List repos you can see: existing mirrors and GitHub repos you could onboard",
669			Long: "List repos visible from your login in one table: existing mirrors " +
670				"(clone URL, clone status) and GitHub repos you could onboard " +
671				"(access, availability). Sparse cells show '-'.\n\n" +
672				"The first " + strconv.Itoa(coreListFetchBudget) + " entries are fetched by default, with a note on stderr " +
673				"when more exist. Filters and --sort apply to those fetched rows — add " +
674				"--all to work over the complete list, or --limit N for just the first N.\n\n" +
675				"For manual paging, --page-size/--page-token fetch one page at a time; " +
676				"with --json the rows come wrapped in an {items, nextPageToken} envelope.",
