683				}
684				if err := validatePageSize(cmd, pageSize); err != nil {
685					return err
686				}
687				_, _, err := parseSortColumn(sortSpec, repoDirColumns)
688				return err
689			},
690			RunE: func(cmd *cobra.Command, _ []string) error {
691				// The client-side pipeline is shared by both modes:
692				// every filter and the sort run over whatever rows the server
