705					// reported for resumption. The client-side local pipeline
706					// applies to just this page; the cursor survives filtering.
707					return flushThroughPager(cmd, noPager, func() error {
708						return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
709							hostBySlug, err := fetchRepoDirCatalog(ctx, cmd, c)
710							if err != nil {
711								return err
712							}
713							params := coreapi.ListReposParams{Scope: coreapi.NewOptListReposScope(coreapi.ListReposScopeAll)}
