716							}
717							if pageSize > 0 {
718								params.PageSize = coreapi.NewOptInt32(int32(pageSize)) //nolint:gosec // G115: validatePageSize bounds it
719							}
720							out, err := c.ListRepos(ctx, params)
721							if err != nil {
722								return err
723							}
724							next := out.NextPageToken.Or("")
725							// A truncated page the cursor can resume past needs no
726							// warning — the resume hint covers it. Truncated with no
727							// cursor means unreachable repos.
728							if out.Truncated && next == "" {
729								warnRepoDirTruncated(cmd)
730							}
731							rows, err := applyLocal(buildRepoDir(out.Repos, hostBySlug), hostBySlug)
732							if err != nil {
733								return err
734							}
735							return renderCoreListPage(cmd, "No repos found.", columnHeaders(repoDirColumns), repoDirCells, rows, next)
736						})
737					})
738				}
739				// Buffer the rendered table so long TTY output can go through a
740				// pager; the row set is fully materialized for the client-side sort
741				// anyway, so buffering the render adds nothing.
742				return flushThroughPager(cmd, noPager, func() error {
743					return runCoreList(cmd, "No repos found.", columnHeaders(repoDirColumns), repoDirCells, func(ctx context.Context, c *coreapi.Client) ([]repoDirRow, error) {
744						hostBySlug, err := fetchRepoDirCatalog(ctx, cmd, c)
745						if err != nil {
746							return nil, err
747						}
748						// The server cannot filter or sort this directory, so the whole
749						// pipeline below is local. Bound what one call fetches: the
750						// budget caps the cursor walk (raised to --limit when larger,
751						// lifted entirely by --all) so a huge org pays for a few pages,
752						// not thousands — at the disclosed price of filters and sort
753						// seeing only the fetched window.
754						budget := max(coreListFetchBudget, limit)
755						if all {
756							budget = 0 // unbounded
757						}
758						truncated := false
759						repos, partial, err := fetchPagesBounded(ctx, budget, func(ctx context.Context, cursor string) ([]coreapi.RepoIndexEntry, string, error) {
760							params := coreapi.ListReposParams{Scope: coreapi.NewOptListReposScope(coreapi.ListReposScopeAll)}
761							if cursor != "" {
762								params.PageToken = coreapi.NewOptString(cursor)
763							}
764							out, lerr := c.ListRepos(ctx, params)
765							if lerr != nil {
766								return nil, "", lerr
767							}
768							next := out.NextPageToken.Or("")
769							// A capped page mid-chain is fine — the cursor walks past it.
770							// Only a capped page with no cursor to continue from (legacy
771							// server, or a hard directory cap) leaves repos unseen, and a
772							// short directory must not read as "this is everything".
773							truncated = truncated || (out.Truncated && next == "")
