795						}
796						// Cap last, after filters and the sort, so --limit N always
797						// means "the first N rows of the table you would have seen".
798						if limit > 0 && len(rows) > limit {
799							rows = rows[:limit]
800						}
801						return rows, nil
802					})
803				})
804			},
