// completeMirrorOwnerRepo is the ValidArgsFunction for `mirror get`: it offers
// the caller-visible mirrors' owner/repo names (the `mirror list` NAME cell),
// each annotated with its cluster hosts, so the drill-down needs a TAB, not a
// copy-paste. One bounded ListMirrors page — completion runs on every TAB
// press, so it must stay fast and fail silent (an error just yields no
// suggestions; cobra applies the prefix filter). ULID and clone-URL refs stay
// typeable but aren't offered.
func completeMirrorOwnerRepo(cmd *cobra.Command, args []string, _ string) ([]string, cobra.ShellCompDirective) {
	if len(args) != 0 {
		// <mirror> is a single positional; nothing to complete past it.
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	ctx, cancel := context.WithTimeout(cmd.Context(), completeMirrorTimeout)
	defer cancel()
	c, err := activeCoreClient(ctx)
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	out, err := c.ListMirrors(ctx, coreapi.ListMirrorsParams{})
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	// A multi-cluster repo appears once per cluster in /mirrors; offer it
	// once, its clusters joined into the completion description.
	hostsByName := make(map[string][]string)
	names := make([]string, 0, len(out.Mirrors))
	for _, m := range out.Mirrors {
		name := m.Owner + "/" + m.Repo
		if _, seen := hostsByName[name]; !seen {
			names = append(names, name)
		}
		hostsByName[name] = append(hostsByName[name], m.ClusterHost)
	}
	slices.Sort(names)
	comps := make([]string, 0, len(names))
	for _, name := range names {
		comps = append(comps, name+"\t"+strings.Join(hostsByName[name], ", "))
	}
	return comps, cobra.ShellCompDirectiveNoFileComp
}

// completeMirrorTimeout bounds the completion round-trip: a TAB press must
// degrade to "no suggestions" rather than hang the shell on a slow core.
const completeMirrorTimeout = 2 * time.Second

// parseOwnerRepoRef reads a bare <owner>/<repo> mirror reference — the NAME
// cell of `mirror list`. Anything carrying a scheme, extra path segments, or
// an empty side is not this form (it falls through to clone-URL parsing, whose
// error names the expected shapes).

// TestCompleteMirrorOwnerRepo pins `mirror get` TAB completion: the
// caller-visible mirrors' owner/repo names, deduped across clusters (the
// cluster hosts land in the completion description instead), sorted, and
// failing silent — a broken core yields no suggestions, never an error.
//
// Not parallel: swaps the package-level activeCoreClient seam.
func TestCompleteMirrorOwnerRepo(t *testing.T) {
	seamActive := func(t *testing.T, fn func(context.Context) (*coreapi.Client, error)) {
		t.Helper()
		prev := activeCoreClient
		activeCoreClient = fn
		t.Cleanup(func() { activeCoreClient = prev })
	}
	compCmd := func(t *testing.T) *cobra.Command {
		t.Helper()
		cmd := &cobra.Command{}
		cmd.SetContext(t.Context())
		return cmd
	}

	t.Run("offers deduped owner/repo names with clusters as description", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			w.Header().Set("Content-Type", "application/json")
			assert.NoError(t, printJSON(w, &coreapi.ListMirrorsOutputBody{Mirrors: []coreapi.Mirror{
				{Owner: "entirehq", Repo: "entiredb", ClusterHost: "aws-us-east-2.entire.io"},
				{Owner: "acme", Repo: "web", ClusterHost: "eu-west-1.entire.io"},
				{Owner: "entirehq", Repo: "entiredb", ClusterHost: "eu-west-1.entire.io"},
			}}))
		}))
		t.Cleanup(srv.Close)
		seamActive(t, func(context.Context) (*coreapi.Client, error) {
			return coreapi.NewWithBearer(srv.URL, "tok")
		})

		comps, directive := completeMirrorOwnerRepo(compCmd(t), nil, "")
		require.Equal(t, cobra.ShellCompDirectiveNoFileComp, directive)
		require.Equal(t, []string{
			"acme/web\teu-west-1.entire.io",
			"entirehq/entiredb\taws-us-east-2.entire.io, eu-west-1.entire.io",
		}, comps, "one entry per repo, clusters joined in the description")
	})

	t.Run("a core error yields no suggestions, silently", func(t *testing.T) {
		seamActive(t, func(context.Context) (*coreapi.Client, error) {
			return nil, errors.New("no active context")
		})
		comps, directive := completeMirrorOwnerRepo(compCmd(t), nil, "")
		require.Empty(t, comps)
		require.Equal(t, cobra.ShellCompDirectiveNoFileComp, directive)
	})

	t.Run("a filled positional completes nothing further", func(t *testing.T) {
		seamActive(t, func(context.Context) (*coreapi.Client, error) {
			t.Error("no call expected once the positional is filled")
			return nil, errors.New("no dial expected")
		})
		comps, _ := completeMirrorOwnerRepo(compCmd(t), []string{"acme/web"}, "")
		require.Empty(t, comps)
	})
}

