211	// fetchAllPages drives a keyset-paginated list endpoint to completion: it
212	// calls fetch with an empty cursor, then re-calls it with each returned
213	// nextPageToken until the cursor comes back empty, concatenating every page.
214	// The control plane caps the page size (and may cap it further than a caller
215	// requests), so a single call only returns one page — list commands must loop
216	// or they silently truncate.
217	func fetchAllPages[T any](ctx context.Context, fetch func(ctx context.Context, cursor string) (items []T, next string, err error)) ([]T, error) {
218		items, _, err := fetchPagesBounded(ctx, 0, fetch)
