110	// totalTokens recursively sums all token fields including subagent tokens.
111	func totalTokens(tu *agent.TokenUsage) int {
112		if tu == nil {
113			return 0
114		}
115		total := saturatingIntAdd(tu.InputTokens, tu.CacheCreationTokens)
116		total = saturatingIntAdd(total, tu.CacheReadTokens)
117		total = saturatingIntAdd(total, tu.OutputTokens)
118		total = saturatingIntAdd(total, totalTokens(tu.SubagentTokens))
119		return total
120	}
