266		prefix := "── "
267		content := label + " "
268		usedWidth := len([]rune(prefix)) + len([]rune(content))
269		trailing := width - usedWidth
270		if trailing < 1 {
271			trailing = 1
272		}
273	
274		var b strings.Builder
275		b.WriteString(s.render(s.dim, "── "))
276		b.WriteString(s.render(s.dim, label))
277		b.WriteString(" ")
278		b.WriteString(s.render(s.dim, strings.Repeat("─", trailing)))
279		return b.String()
